#ifdef TEST_BUBBLE_E2E
static void
test_bubble_e2e (void)
{
  printf ("\n=== Group: bubble_e2e (bubble sort; vs std::sort) ===\n");
  // Was: one 5-element array with five literal element checks -- no duplicates,
  // no already-sorted or reversed input, no n = 0 or 1, and nothing that would
  // catch a lost or duplicated element.  std::sort is the reference; the
  // multiset check is separate from the ordering check because a sort can fail
  // either by mis-ordering OR by dropping/duplicating a value, and comparing
  // only against a sorted copy conflates the two.
  //
  // The .sis is `A1[j: old A1[j+1], old A1[j]]` -- a two-value replace at j,
  // i.e. the swap.  n <= 1 must leave the input alone (the outer `while
  // limit > 1` never trips).
  struct Case { const char *nm; std::vector<int32_t> v; };
  const std::vector<Case> cases = {
    { "the original 5", { 5, 1, 4, 2, 8 } },
    { "already sorted", { 1, 2, 3, 4, 5, 6 } },
    { "reverse sorted", { 9, 7, 5, 3, 1 } },
    { "all equal", { 4, 4, 4, 4 } },
    { "duplicates either side of the pivot value", { 3, 1, 3, 2, 1, 3, 2 } },
    { "negatives and zero", { 0, -3, 7, -1, 0, 2, -3 } },
    { "single element", { 42 } },
    { "two, out of order", { 2, 1 } },
    { "two, in order", { 1, 2 } },
    { "extremes", { 2147483647, -2147483647 - 1, 0 } },
  };
  bool ordered_ok = true, multiset_ok = true, n_ok = true;
  int total = 0;
  for (const auto &c : cases)
    {
      std::vector<int32_t> want = c.v;
      std::sort (want.begin (), want.end ());
      std::vector<int32_t> in = c.v;
      sisal_array_t va = make_int_arr (in.data (), (int)in.size ());
      sisal_array_t r = func_BUBBLE ((int32_t)in.size (), va);
      if ((int)r.size != (int)in.size ()) { n_ok = false; }
      else
        {
          std::vector<int32_t> got ((const int32_t *)r.data,
                                    (const int32_t *)r.data + r.size);
          if (got != want) ordered_ok = false;
          // same elements with the same multiplicities, independent of order
          std::vector<int32_t> gs = got, cs = c.v;
          std::sort (gs.begin (), gs.end ());
          std::sort (cs.begin (), cs.end ());
          if (gs != cs) multiset_ok = false;
          total += (int)got.size ();
        }
      // the sort may return its INPUT buffer unchanged (already-sorted, n = 1),
      // so the result can alias the argument -- freeing both is a double free
      if (r.data && r.data != va.data) free (r.data);
      free (va.data);
    }
  char msg[128];
  snprintf (msg, sizeof msg,
            "%zu inputs (%d elements) sort exactly as std::sort does",
            cases.size (), total);
  check (msg, ordered_ok);
  check ("...and every result is a permutation of its input -- nothing dropped "
         "or duplicated",
         multiset_ok);
  check ("...with the length preserved throughout", n_ok);

  // n = 0 and n = 1 never enter the outer loop
  {
    std::vector<int32_t> one = { 7 };
    sisal_array_t va = make_int_arr (one.data (), 1);
    sisal_array_t r = func_BUBBLE (1, va);
    check ("n = 1 returns the input untouched (the outer while never trips)",
           (int)r.size == 1 && ((const int32_t *)r.data)[0] == 7);
    if (r.data && r.data != va.data) free (r.data);
    free (va.data);
  }
}
#endif
#ifdef TEST_LEGPOLY_DV_E2E
static void
test_legpoly_dv_e2e (void)
{
  printf ("\n=== Group: legpoly_dv_e2e (associated Legendre, 1st kind; vs C "
          "reference) ===\n");
  // Was: eight constants of 6-8 digits, no provenance, reading 9 of 16
  // elements at ir = 2 -- which takes the `IF ir = 2 THEN pp` short-circuit,
  // so the entire second nest (the ppp / p4 three-term recurrence, about half
  // the program) never ran.  legpoly_ref.h covers both paths; every element is
  // compared, and ir > 2 is exercised.
  struct { int ir, irmax2, jxxmx; } cases[]
      = { { 2, 4, 16 }, { 2, 5, 20 }, { 3, 4, 20 }, { 4, 4, 24 }, { 5, 3, 28 } };
  const float coa = 0.5f, sia = 0.8660254f, delta = 1.04719755f;
  int elems = 0;
  bool ok = true, sized = true, second_nest_live = false;
  for (auto c : cases)
    {
      // no runtime subscript checking: if the array is too short for these
      // parameters the program writes past the end silently, so refuse to run
      if (c.jxxmx < legpolyref::min_size (c.ir, c.irmax2)) { sized = false; continue; }
      const std::vector<double> w
          = legpolyref::ref_legpoly (c.ir, c.irmax2, c.jxxmx, coa, sia, delta);
      sisal_array_t r = func_LEGENDREPOLYOF1STKIND (c.ir, c.irmax2, c.jxxmx,
                                                    coa, sia, delta);
      bool this_ok = ((int)r.size == c.jxxmx);
      for (int k = 1; this_ok && k <= c.jxxmx; k++)
        {
          const double got = ((const double *)r.data)[k - 1];
          const double scale = std::max (1.0, fabs (w[k]));
          if (fabs (got - w[k]) > 1e-9 * scale) this_ok = false;
          elems++;
        }
      if (c.ir > 2)
        {
          // the second nest must actually have written something, or "matches"
          // proves nothing about the path it was added to cover
          const int first_only = c.ir + 2 + c.irmax2;
          for (int k = first_only + 1; k <= c.jxxmx; k++)
            if (w[k] != 0.0) second_nest_live = true;
        }
      char msg[128];
      snprintf (msg, sizeof msg,
                "ir=%d irmax2=%d jxxmx=%d: all %d elements match the C "
                "reference%s",
                c.ir, c.irmax2, c.jxxmx, c.jxxmx,
                c.ir == 2 ? "" : "  (second nest)");
      check (msg, this_ok);
      ok = ok && this_ok;
      if (r.data) free (r.data);
    }
  check ("every case is large enough for its parameters (no silent overrun)",
         sized);
  check ("the ir > 2 cases really drive the ppp/p4 recurrence past the first "
         "nest's last index",
         second_nest_live);
  char msg[96];
  snprintf (msg, sizeof msg, "%d element comparisons against the reference",
            elems);
  check (msg, ok && elems > 100);
}
#endif
#ifdef TEST_NESTED_INIT_MERGE_DV
static void
test_nested_init_merge_dv (void)
{
  printf ("\n=== Group: nested_init_merge_dv (nested for-initial, captured "
          "carry) ===\n");
  // THE VALUES ARE NOT ASSERTED, DELIBERATELY.  The inner loop is
  //
  //     for initial k := p; i := 0; Xt := old A;
  //     while ( k <= n ) repeat
  //       k := old k + 1; i := old i + 1;
  //       Xt := old Xt[i: old Xt[k] + 1.0d0];
  //
  // pre-test on k, with k incremented BEFORE it is used as a subscript.  The
  // last admitted test is k = n, and the body then indexes Xt[n+1] -- one past
  // the end, on every inner loop, for every p and every n.  There is no runtime
  // subscript checking, so that read returns whatever follows the buffer.
  //
  // Worked by hand for n = 3 on [1,3,5] the result is [1,1,1], and the program
  // does return [1,1,1] -- but only because the out-of-bounds read yields 0.
  // Pinning that would be pinning undefined behaviour, so this checks only what
  // is well defined: the shape, and that the nest ran without trapping.  Not
  // fixable by choosing a different input; the overrun is in the program.
  bool ok = true;
  for (int n : { 1, 3, 5 })
    {
      std::vector<double> x;
      for (int k = 0; k < n; k++) x.push_back (1.0 + 2.0 * k);
      sisal_array_t X = ewref::mkd (x);
      sisal_array_t r = func_MAIN (n, X);
      ok = ok && (r.rank == 1) && ((int)r.size == n);
      for (int k = 0; ok && k < n; k++)
        ok = std::isfinite (ad (r, k));   // finite, but not a pinned value
      free (X.data);
      if (r.data && r.data != X.data) free (r.data);
    }
  check ("nested for-initial returns a rank-1 array of n finite doubles for "
         "n = 1, 3, 5 (values unasserted: the inner loop reads Xt[n+1])",
         ok);
}
#endif
